<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/pagination.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/reception_service.php';
try{$uid=(int)requireAuth()->id;$c=db();requirePermission($c,$uid,'supplierReceptions.view');[$page,$size,$offset]=paginationInput($_GET);$search=trim((string)($_GET['search']??''));$status=strtoupper(trim((string)($_GET['status']??'')));$supplierOrderId=max(0,(int)($_GET['supplier_order_id']??0));$where=['sr.user_id=?'];$types='i';$args=[$uid];if($search!==''){$where[]="CONCAT_WS(' ',sr.invoice_number,s.name,sr.status,so.order_number) LIKE ?";$types.='s';$args[]='%'.$search.'%';}if($status!==''){$where[]='sr.status=?';$types.='s';$args[]=$status;}if($supplierOrderId>0){$where[]='sr.supplier_order_id=?';$types.='i';$args[]=$supplierOrderId;}$w=implode(' AND ',$where);$join=' FROM erp_supplier_receptions sr JOIN suppliers s ON s.id=sr.supplier_id AND s.user_id=sr.user_id LEFT JOIN erp_supplier_orders so ON so.id=sr.supplier_order_id AND so.user_id=sr.user_id';$q=$c->prepare("SELECT COUNT(*) total,ROUND(COALESCE(SUM(sr.total_ttc),0),3) amount $join WHERE $w");$q->bind_param($types,...$args);$q->execute();$agg=$q->get_result()->fetch_assoc();$q->close();$q=$c->prepare("SELECT sr.*,s.name supplier_name,so.order_number $join WHERE $w ORDER BY sr.id DESC LIMIT ? OFFSET ?");$qt=$types.'ii';$qa=[...$args,$size,$offset];$q->bind_param($qt,...$qa);$q->execute();$headers=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();$rows=[];if($headers){$ids=array_map(fn($r)=>(int)$r['id'],$headers);$idSql=implode(',',$ids);$ir=$c->query("SELECT * FROM erp_supplier_reception_items WHERE supplier_reception_id IN($idSql) ORDER BY id");$by=[];while($item=$ir->fetch_assoc())$by[(int)$item['supplier_reception_id']][]=supplierReceptionLineRow($item);$ir->close();foreach($headers as $h)$rows[]=supplierReceptionRow($h,$by[(int)$h['id']]??[]);}$total=(int)$agg['total'];unset($agg['total']);paginatedResponse($rows,$page,$size,$total,$agg);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>'Could not load supplier receptions.','error_code'=>'SUPPLIER_RECEPTION_LIST_FAILED'],500);}
